//! Sparse 64-bit byte addresses, explicit permissions and bounded allocation.
const std = @import("std");
pub const PAGE_SIZE = 4096;
const Page = [PAGE_SIZE]u8;
pub const Permissions = struct { read: bool = false, write: bool = false, execute: bool = false };
pub const Region = struct { start: u64, size: u64, permissions: Permissions };
pub const Limits = struct { max_mapped_bytes: u64 = 256 * 1024 * 1024, max_pages: usize = 65536 };
pub const Error = std.mem.Allocator.Error || error{ AddressOverflow, UnmappedAddress, AccessDenied, MisalignedAddress, OverlappingRegion, ResourceLimit, InvalidRegion };
pub const Memory = struct {
    allocator: std.mem.Allocator,
    limits: Limits,
    regions: std.ArrayList(Region) = .empty,
    pages: std.AutoHashMap(u64, *Page),
    mapped_bytes: u64 = 0,

    pub fn init(allocator: std.mem.Allocator, limits: Limits) Memory {
        return .{ .allocator = allocator, .limits = limits, .pages = std.AutoHashMap(u64, *Page).init(allocator) };
    }

    pub fn deinit(self: *Memory) void {
        var it = self.pages.valueIterator();
        while (it.next()) |page| self.allocator.destroy(page.*);
        self.pages.deinit();
        self.regions.deinit(self.allocator);
    }

    pub fn map(self: *Memory, region: Region) Error!void {
        if (region.size == 0) return error.InvalidRegion;
        const last = try endAddress(region.start, region.size);
        if (region.size > self.limits.max_mapped_bytes - self.mapped_bytes) return error.ResourceLimit;
        for (self.regions.items) |existing| {
            const existing_last = try endAddress(existing.start, existing.size);
            if (region.start <= existing_last and existing.start <= last) return error.OverlappingRegion;
        }
        try self.regions.append(self.allocator, region);
        self.mapped_bytes += region.size;
    }

    const Access = enum { read, write, execute, initialize };
    fn check(self: *const Memory, address: u64, size: u64, access: Access) Error!void {
        const last = try endAddress(address, size);
        // ELF segment boundaries may fall within a page. Check each byte range,
        // not just a page tag, to avoid granting neighbouring data execute access.
        var cursor = address;
        while (true) {
            var found = false;
            for (self.regions.items) |region| {
                const end = try endAddress(region.start, region.size);
                if (cursor < region.start or cursor > end) continue;
                const allowed = switch (access) {
                    .read => region.permissions.read,
                    .write => region.permissions.write,
                    .execute => region.permissions.execute,
                    .initialize => true,
                };
                if (!allowed) return error.AccessDenied;
                if (end >= last) return;
                cursor = end + 1;
                found = true;
                break;
            }
            if (!found) return error.UnmappedAddress;
        }
    }

    fn byte(self: *const Memory, address: u64) u8 {
        const page = self.pages.get(address / PAGE_SIZE) orelse return 0;
        return page[@intCast(address % PAGE_SIZE)];
    }

    pub fn load(self: *const Memory, address: u64, width: u4) Error!u64 {
        try aligned(address, width);
        try self.check(address, width, .read);
        return self.readUnchecked(address, width);
    }

    pub fn fetch(self: *const Memory, address: u64) Error!u32 {
        try aligned(address, 4);
        try self.check(address, 4, .execute);
        return @intCast(self.readUnchecked(address, 4));
    }

    fn readUnchecked(self: *const Memory, address: u64, width: u4) u64 {
        var result: u64 = 0;
        for (0..width) |i| result |= @as(u64, self.byte(address + i)) << @as(u6, @intCast(i * 8));
        return result;
    }

    pub fn store(self: *Memory, address: u64, width: u4, value: u64) Error!void {
        try aligned(address, width);
        try self.check(address, width, .write);
        var bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &bytes, value, .little);
        try self.put(address, bytes[0..width]);
    }

    /// Loader-only mutation; execution must use store(), which checks write access.
    pub fn initialize(self: *Memory, address: u64, bytes: []const u8) Error!void {
        if (bytes.len == 0) return;
        try self.check(address, bytes.len, .initialize);
        try self.put(address, bytes);
    }

    fn put(self: *Memory, address: u64, bytes: []const u8) Error!void {
        const first = address / PAGE_SIZE;
        const last = (try endAddress(address, bytes.len)) / PAGE_SIZE;
        var missing: usize = 0;
        var index = first;
        while (true) : (index += 1) {
            if (!self.pages.contains(index)) missing += 1;
            if (index == last) break;
        }
        if (missing > self.limits.max_pages - self.pages.count()) return error.ResourceLimit;
        // Reserve all backing pages before changing architectural bytes. On OOM,
        // any retained zero pages do not change the observable memory state.
        try self.pages.ensureUnusedCapacity(@intCast(missing));
        index = first;
        while (true) : (index += 1) {
            if (!self.pages.contains(index)) {
                const page = try self.allocator.create(Page);
                @memset(page, 0);
                self.pages.putAssumeCapacity(index, page);
            }
            if (index == last) break;
        }
        for (bytes, 0..) |value, i| self.pages.get((address + i) / PAGE_SIZE).?[@intCast((address + i) % PAGE_SIZE)] = value;
    }
};

pub fn endAddress(address: u64, size: u64) Error!u64 {
    if (size == 0) return error.InvalidRegion;
    return std.math.add(u64, address, size - 1) catch error.AddressOverflow;
}

fn aligned(address: u64, width: u4) Error!void {
    if (width != 1 and width != 2 and width != 4 and width != 8) return error.InvalidRegion;
    if (address % width != 0) return error.MisalignedAddress;
}

